insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1b513bf0-055a-46fd-973d-38cfb88f4ca0', 'de', 'Welches Blickverhalten unterstützt einen guten ersten Eindruck?', '["Ruhiger Blickkontakt", "Natürliche Pausen", "Ein freundlicher Ausdruck", "Starres Anstarren"]'::jsonb, 'Ausgewogener, freundlicher Blickkontakt signalisiert Sicherheit und Leichtigkeit.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1b9394c8-71a4-4281-9046-5014c86b7514', 'de', 'Du sprichst sie an. Sie reagiert herzlich, aber dann packt ihre Freundin sie am Arm und zieht sie weg.', '["Höflich: Sie war nur nett, bevor die Freundin dazwischenkam", "Zuerst offen, aber eine Störung von außen hat es beendet", "Kühl: Sie hat die Freundin als Ausrede benutzt, um wegzukommen"]'::jsonb, 'Ihre herzliche Reaktion war offen. Die Freundin ist ein äußerer Faktor, kein Signal von ihr.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1ccbf131-6df9-4829-afc6-793d8a586ba6', 'de', 'Sie lächelt dich an. Du fängst an, deinen Opener zu planen. Was tust du am besten?', '["Üben, was du sagst, und dann hingehen", "Sofort hingehen, auch ohne ausgefeilten Satz", "Warten, bis sie dich zur Bestätigung noch mal ansieht"]'::jsonb, 'Schnelles Handeln verhindert, dass Zweifel aufkommen. Geh los, spätestens drei Sekunden nachdem du sie bemerkt hast.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('21c693ec-ce2c-4a1c-b6a4-e5c07cc9e39f', 'de', 'Du sprichst so leise, dass sie Lücken selbst füllen muss. Was entsteht dadurch?', '["Sofort starke Anziehung", "Eine perfekt abgestimmte Präsenz", "Eine geheimnisvolle, spannende Ausstrahlung", "Reibung, die den Gesprächsfluss stört"]'::jsonb, 'Wenn man dich schlecht versteht, kommt unnötige Anspannung ins Gespräch.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('21ca0984-0243-415e-ab95-8d472e631a12', 'de', 'Du gehst in einem Straßencafé auf eine Frau zu. Welche Bewegungen strahlen Gelassenheit aus?', '["Schnelle, hastige Schritte mit hochgezogenen Schultern", "Steife Arme am Körper und ein hölzerner Gang", "Gleichmäßiges Tempo, natürlich schwingende Arme und aufrechte Haltung", "Zögerliche Schritte mit Blick auf den Boden"]'::jsonb, 'Entspannte Bewegungen vermitteln Sicherheit, und das Gespräch fällt ihr leichter.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('243e45da-4e6e-4747-bd72-4c71c92d582b', 'de', 'Du siehst sie, bist aber schlecht angezogen. Was solltest du tun?', '["Trotzdem ansprechen", "Es lassen, dein Aussehen schadet deinen Chancen", "Warten, bis du bereit bist", "Blickkontakt suchen, aber nichts sagen"]'::jsonb, 'Wer nur unter perfekten Bedingungen anspricht, spricht kaum jemanden an. Ansprechen kannst du jederzeit.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('24ae814b-7816-4ac9-af4c-f56e4e9d8de9', 'de', 'Warum wirken indirekte Opener weniger störend?', '["Sie vermeiden Stille", "Sie zeigen Selbstbewusstsein", "Sie knüpfen an den Moment an, in dem ihr beide schon seid"]'::jsonb, 'Eine gemeinsame Situation lässt den Einstieg naheliegend wirken, und es fällt leicht, darauf einzugehen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('24ebc378-571a-47ca-a34d-406494e05bf1', 'de', 'Du siehst, dass sie etwas in ihr Notizbuch zeichnet. Welcher Opener zeigt Neugier?', '["„Du siehst künstlerisch aus.“", "„Kann ich mich hier hinsetzen?“", "„Du bist talentiert, das sieht man.“", "„Was zeichnest du da? Sieht ganz schön detailliert aus.“"]'::jsonb, 'Neugier auf ihre Erlebnisse lädt zu einer echten Verbindung ein, ohne Hintergedanken.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('26e9ec88-6ad1-419a-a087-c91efb8998d2', 'de', 'Welche Gewohnheiten helfen dir, langfristig regelmäßig anzusprechen?', '["Jeden Tag mit Leuten reden", "Warten, bis du dich bereit fühlst", "An ganz alltäglichen Orten ins Gespräch kommen"]'::jsonb, 'Regelmäßiger Kontakt senkt den Druck, und Begegnungen fallen dir leichter.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2726ad43-344c-4ec6-a996-4df4d37978f4', 'de', 'Du siehst eine Frau mit einem außergewöhnlichen Accessoire. Womit könntest du einsteigen, um sie neugierig zu machen?', '["„Woher hast du das?“", "„Ich hab eine kurze Frage zu dem, was du da trägst.“", "„Cool, gefällt mir.“", "„Bist du von hier?“"]'::jsonb, 'Die Ankündigung macht neugierig, bevor du die eigentliche Frage stellst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('29a122e7-d801-4e7c-bf05-40a46aba0960', 'de', 'Sie steht allein in der Schlange. Du willst sie nach ihrer Meinung fragen. Bester Opener?', '["„Hey, wie läuft dein Tag?“", "„Kurze Frage: Kaffee- oder Teetyp?“", "„Was meinst du, ist hier das Saisongetränk besser oder das normale?“"]'::jsonb, 'Eine kleine Streitfrage lädt sie ein, ihre Meinung zu sagen. So fühlt sie sich geschätzt und einbezogen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2ada2eb4-7e4e-4ea9-b9d1-7cde29ea6304', 'de', 'Sie dreht sich kaum um und sagt tonlos „hey“. Was signalisiert das?', '["Schüchternheit", "Neugier", "Neutrales Interesse", "Eine kühle Reaktion"]'::jsonb, 'Kaum Beteiligung heißt: Zieh dich zurück und verabschiede dich sauber.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2b69af0f-cead-4bcb-8f8d-580b110d13f2', 'de', 'Welches Signal zeigt am deutlichsten, dass sie kühl reagiert?', '["Ein kurzes Lächeln", "Sie antwortet auf Fragen", "Sie wendet sich ab", "Ein höfliches Lachen"]'::jsonb, 'Ein abgewandter Körper zeigt Desinteresse. Geh.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2d63f1fb-98b5-4678-aec8-6b0c2abded25', 'de', 'Sie dreht sich zu dir, lächelt herzlich und antwortet ausführlich, schaut aber immer wieder zu ihren Freundinnen.', '["Offen: Dass sie Fragen stellt, zeigt Interesse, auch wenn sie auf ihre Freundinnen achtet", "Höflich: freundlich, aber die wiederholten Blicke zeigen geteilte Aufmerksamkeit", "Neutral: Sie schaut nur nach ihren Freundinnen. Mach normal weiter"]'::jsonb, 'Sie macht höflich mit, aber ihre Aufmerksamkeit ist nicht ganz bei dir.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2f7b8ecd-021a-40d3-aea3-50d2530f7f6e', 'de', 'Sie antwortet freundlich, scrollt aber weiter auf ihrem Handy. Wovon solltest du ausgehen?', '["Sie ist schüchtern", "Sie ist offen", "Sie ist abgelenkt, aber interessiert", "Sie ist höflich"]'::jsonb, 'Geteilte Aufmerksamkeit heißt meist Höflichkeit, kein echtes Interesse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2fa1ad2f-3496-4f7e-b850-7253ba88fd6b', 'de', 'Sie lacht über deinen Opener und wendet sich dir ganz zu, verschränkt aber die Arme. Was passiert da?', '["Offen: Lachen und Zuwendung zeigen Interesse, trotz der Arme", "Höflich: Gezwungenes Lachen mit verschlossener Körpersprache heißt Desinteresse", "Gemischt: Lachen und Zuwendung sind offen, die verschränkten Arme zeigen Unsicherheit"]'::jsonb, 'Lachen zeigt, dass sie sich wohlfühlt, verschränkte Arme zeigen Zurückhaltung. Mach locker weiter.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3583c492-59dd-4eb4-a7c9-c98966901e7d', 'de', 'Sie hat einen außergewöhnlichen Kaffeebecher dabei. Womit könntest du einsteigen, um sie neugierig zu machen?', '["„Ich muss dich was zu dem Kaffeebecher fragen.“", "„Woher hast du den Becher?“", "„Der Becher sieht lustig aus.“", "„Bist du oft hier?“"]'::jsonb, 'Die Ankündigung macht neugierig, bevor du die eigentliche Frage stellst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('36134173-386a-4742-a375-45b16eeb371f', 'de', 'Was brauchst du, um den Rahmen klar zu setzen?', '["Warten, bis sie dir Erlaubnis oder Signale zum Weitermachen gibt", "Das Thema selbst vorgeben, statt dich nur in ihre Welt einzuklinken", "Das Gespräch voranbringen, ohne darauf zu warten, dass sie führt"]'::jsonb, 'Den Rahmen setzen heißt, Thema und Verlauf vorzugeben.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('365d84da-247e-427e-a603-8e7d2900f73f', 'de', 'Sie antwortet freundlich, sagt aber: „Ich sollte bald mal los.“ Was ist das?', '["Höflich mit sanfter Grenze: Sie ist dabei, zeigt aber, dass sie wenig Zeit hat", "Offen: Die freundliche Antwort zeigt Interesse, der Abschied ist nur Höflichkeit", "Gemischt: Ihr Interesse widerspricht dem angekündigten Abschied"]'::jsonb, 'Sie ist rücksichtsvoll und zeigt trotzdem eine Grenze. Nimm das an und verabschiede dich höflich.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3669c3ab-5f36-42cb-932f-6277589d1d8e', 'de', 'Warum ist es wichtig, ihre erste Reaktion zu lesen?', '["Es zwingt sie, offen zu werden", "Es hält das Gespräch für euch beide angenehm", "Es respektiert ihren Raum und ihre Signale", "Es verhindert, dass du Grenzen überschreitest, die sie nicht geöffnet hat"]'::jsonb, 'Wenn du sie richtig liest, bleibt es für euch beide angenehm und entspannt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3717fc9d-129b-426e-a329-a0e904cfd1e1', 'de', 'Sie antwortet knapp, schaut weg und verlagert ihr Gewicht. Was solltest du tun?', '["Es kurz halten und dich elegant verabschieden", "Mit mehr Fragen nachbohren, um sie einzubeziehen", "Einen Schritt weitergehen, um Anziehung aufzubauen", "Ihr ein Kompliment machen, damit sie auftaut"]'::jsonb, 'Neutrale, höfliche Signale heißen: Mach langsamer oder zieh dich zurück, aus Respekt vor ihrem Wohlgefühl.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3763474f-7119-463b-a740-ab5dd1bb8606', 'de', 'Du sprichst sie im Café an, während sie liest. Welcher Opener hält einen starken Rahmen?', '["„Sorry, dass ich störe, aber ich wollte kurz Hallo sagen.“", "„Ist hier noch frei?“", "„Das Buch sieht spannend aus. Worum geht’s?“", "„Entschuldigung, kann ich kurz mit dir reden?“"]'::jsonb, 'Wer einfach davon ausgeht, dass sie mitredet, führt den Rahmen, ohne sich zu entschuldigen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('381417bd-9910-49a2-b9c7-271afc73bcf9', 'de', 'Was ist die Folge, wenn du nichts tust?', '["Garantiertes Scheitern", "Schutz vor einer Abfuhr", "Keine Verbindung und keine Chance", "Reue, die nachhängt"]'::jsonb, 'Nichtstun garantiert verpasste Chancen und Reue, die bleibt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('38ade8d0-fc3e-4396-9791-5b19775afa46', 'de', 'Du sprichst sie auf einer offenen Fläche an. Was solltest du vermeiden?', '["In normalem Gesprächsabstand mit offener Haltung stehen bleiben", "Ihr einen möglichen Weg nach draußen versperren", "Sichtbar aus einem 45-Grad-Winkel kommen", "Etwa einen Meter Abstand halten"]'::jsonb, 'Einen Ausweg zu versperren ist auch auf offenen Flächen unangenehm.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3a61650f-61dd-4d87-b302-9c1fad8a6217', 'de', 'Warum ist Verspieltheit wichtig, wenn du einen Rahmen setzt?', '["Sie nimmt Druck raus, und das Gespräch macht Spaß, statt ernst zu sein", "Ein verspielter Rahmen erzeugt Anziehung durch positive Gefühle", "Sie zeigt, dass du dich wohlfühlst", "Alle oben genannten"]'::jsonb, 'Alles richtig: Verspieltheit nimmt Druck raus, weckt positive Gefühle und zeigt, dass du dich wohlfühlst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3aa54f55-0812-4c14-be64-8fed1f814fb4', 'de', 'Welches Signal unterscheidet Offenheit am besten von Höflichkeit?', '["Lächeln", "Blickkontakt", "Gegenfragen", "Nicken"]'::jsonb, 'Dass sie auf dich eingeht, zeigt Interesse deutlicher als alles andere.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3b44889c-1e0c-4a51-8846-e7d4ea05c95b', 'de', 'Du sprichst sie in der Schlange an. Sie sagt: „Ich hab’s eigentlich eilig.“ Beste Reaktion?', '["„Alles gut, wollte nur Hallo sagen“, und dich locker verabschieden", "Dich entschuldigen, dass du sie störst, und zurücktreten", "Ihren Satz ignorieren und einfach weiterreden"]'::jsonb, 'Erzwing kein Gespräch und entschuldige dich nicht. Halt es locker und geh weiter.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3c06a35a-c102-4ca8-bce5-02e0afa2b5a6', 'de', 'Club. Ihr seid in eine ruhigere Ecke gegangen. Was kommt als Nächstes?', '["Weiterreden und vorschlagen, euch ein andermal zu treffen", "Jetzt ihre Nummer holen, solange der Schwung da ist", "Vorschlagen, gemeinsam woandershin zu gehen", "Ihre Nummer holen oder vorschlagen, gemeinsam weiterzuziehen, je nach Umständen und ihren Signalen"]'::jsonb, 'Bei starkem Schwung ist ein nächster Schritt dran: Sichere dir den Kontakt oder schlag vor, woanders weiterzumachen, wenn ihre Signale Ja sagen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3c98c86a-c4c9-43a5-be53-6cad77bf34c5', 'de', 'Wann solltest du ein Gespräch beenden?', '["Wenn sie kühle Signale sendet: kaum Beteiligung, verschlossene Haltung, abgewandt", "Wenn die höflichen Signale bleiben: knappe Antworten, sie geht kaum auf dich ein", "Wenn Zeit oder Umstände ein Weitermachen unpassend machen", "Alle oben genannten"]'::jsonb, 'Ein sauberer Abschied schützt ihr Wohlgefühl und deinen Rahmen, wenn kein Interesse da ist.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3caf0039-8d00-42c1-8c5a-9b57ae2ac717', 'de', 'Sie sagt: „Ich bin eigentlich gerade beschäftigt“, lächelt aber weiter und bleibt dir zugewandt.', '["Offen: Das Lächeln zählt mehr als die Worte", "Höflich: eine respektvoll geäußerte Grenze", "Gemischt: Hak leicht nach", "Kühl: Jede Grenze ist eine Ablehnung"]'::jsonb, 'Eine klare Grenze mit Freundlichkeit ist ein höflicher Rückzug.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3dfb88ca-871e-4a7e-b233-6335a1bd949a', 'de', 'Ihr unterhaltet euch, und du merkst, dass ihre Freundin in der Nähe wartet. Was tust du am besten?', '["Die Freundin ignorieren und weitermachen", "Um Aufmerksamkeit konkurrieren", "Die Freundin kurz einbeziehen und dann neu einschätzen", "Sofort einen Schritt weitergehen"]'::jsonb, 'Wenn du sie einbeziehst, sinkt die Anspannung, und du behältst die Führung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3ebc28c1-d1f2-41ee-a393-af6d74a978a9', 'de', 'Sie lacht, wendet sich aber immer wieder ab. Was zählt mehr?', '["Ihr Lachen", "Dein Opener", "Ihre Körpersprache", "Die Umgebung"]'::jsonb, 'Wenn sich Signale widersprechen, vertrau dem Körper. Lass ihr Raum oder zieh dich zurück, wenn sie sich abwendet.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('40d53e0a-03ba-435a-8d62-e1fcb096eded', 'de', 'Was lässt einen indirekten Opener natürlich wirken, sodass sie leicht darauf eingehen kann?', '["Etwas Cleveres oder Beeindruckendes sagen", "Eine gemeinsame Umgebung oder ein Moment, den ihr beide erlebt", "Perfektes Timing"]'::jsonb, 'Eine gemeinsame Situation lässt den Einstieg naheliegend wirken, und es fällt leicht, darauf einzugehen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4232f870-74a7-4557-9e29-70a586b48204', 'de', 'Du siehst sie in einer Bar. Wie sieht die direkte Ansprache aus?', '["Etwas zur Musik oder zu den Drinks sagen, um ins Gespräch zu kommen", "Blickkontakt suchen und lächeln", "„Du bist mir aufgefallen, ich wollte mich kurz vorstellen.“"]'::jsonb, 'Direkte Opener sagen gleich offen, dass du romantisches Interesse hast.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('478e1b59-9821-4b03-8744-b950a6269270', 'de', 'Du siehst eine Frau mit einer Vintage-Uhr. Welcher Opener bringt sie ins Gespräch?', '["„Hi, wie geht’s dir heute Abend?“", "„Du siehst gut aus.“", "„Was machst du beruflich?“", "„Die Uhr sieht aus, als hätte sie eine Geschichte.“"]'::jsonb, 'Eine konkrete Vermutung bringt sie dazu, sich einzubringen und persönlich zu antworten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('48e4513c-c89e-4a8b-99e3-d70a28ea7193', 'de', 'In der Schlange sagst du: „Du wirkst viel zu entspannt für diese Schlange.“ Sie lacht. Was funktioniert hier?', '["Du hast die gemeinsame Situation aufgegriffen", "Du hast einen verspielten Kontrast geschaffen", "Du hast um Erlaubnis gefragt, etwas zu sagen"]'::jsonb, 'Gemeinsame Situation plus Verspieltheit baut Widerstand schnell ab.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4de13376-2210-4667-8d5f-ae59a38657c2', 'de', 'Warum ist ein einzelner, direkter Schritt besser als Herumtrödeln, um ihr Interesse zu klären?', '["Er verkürzt das Gespräch", "Er zeigt Führung", "Er verhindert eine Abfuhr", "Er gibt ihr Klarheit und die Kontrolle"]'::jsonb, 'Ein klarer Satz räumt Unklarheit aus und zeigt, ob hinter ihrer Freundlichkeit Interesse steckt oder nur Höflichkeit.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4ef57d59-ef61-4420-92a6-2b920652d1b8', 'de', 'Warum fühlen sich Menschen durch Opener, die nach ihrer Meinung fragen, geschätzt?', '["Indem du nach ihrer Sicht fragst, zeigst du klar, dass ihr Urteil zählt", "Nach Meinungen zu fragen zeigt emotionale Intelligenz und soziales Geschick", "Menschen reden lieber über sich, als zuzuhören"]'::jsonb, 'Menschen blühen auf, wenn ihre Sicht zählt. Wertschätzung weckt Interesse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4fe08740-af66-4896-aa93-6a50f2a41020', 'de', 'Sie sagt: „Ich wollte eigentlich gerade los“, bleibt aber stehen und stellt dir weiter Fragen.', '["Höflicher Rückzug", "Gemischtes Signal, eher offen", "Kühles Signal, höflich verpackt", "Klare Ablehnung"]'::jsonb, 'Dass sie bleibt und weiter neugierig ist, zeigt Offenheit, auch wenn sie eigentlich losmuss.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5027deaf-2157-42e1-b4db-138c9801e876', 'de', 'Sie lächelt und antwortet positiv, sagt aber: „Ich lerne eigentlich gerade für eine Prüfung.“', '["Offen: Die positive Antwort zeigt Interesse, trotz der Prüfung", "Höfliche Absage: Sie ist nett, aber das Lernen ist eine Grenze", "Test: Sie will sehen, ob du dranbleibst oder ihre Prioritäten respektierst"]'::jsonb, 'Ein freundlicher Ton kann Höflichkeit sein. Eine genannte Priorität ist eine Grenze. Wünsch ihr viel Glück und geh.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('50916cec-9c9c-486c-b266-a45065ff3ea2', 'de', 'Sie antwortet begeistert und stellt eine Nachfrage, schaut aber ständig aufs Handy.', '["Offen: Was sie sagt, zeigt echtes Interesse, trotz Handy", "Höflich: Der Blick aufs Handy widerspricht der Herzlichkeit und zeigt geteilte Aufmerksamkeit", "Gemischt: Ihre Worte sind offen, aber ihr Verhalten deutet auf Ablenkung hin"]'::jsonb, 'Gemischte Signale brauchen Feingefühl. Mach kurz weiter und schau, ob ihre Aufmerksamkeit zurückkommt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51786178-0f86-4cb1-b4bd-0b3e68a87f9e', 'de', 'Warum ist es riskant, Höflichkeit für Interesse zu halten?', '["Es bremst das Gespräch aus", "Es setzt sie ungewollt unter Druck", "Es lässt die Ansprache mutig wirken"]'::jsonb, 'Ihr Wohlgefühl kommt zuerst. Nutz die Signale, um zu entscheiden, ob du weitermachst oder dich zurücknimmst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51944bdf-42d0-42e5-b902-ff0f21714718', 'de', 'Sie ist herzlich, lacht und stellt Fragen, sagt aber: „Ich hab eigentlich einen Freund.“', '["Offen: Ihr Interesse ist da, der Freund ist nur ein Test", "Höflich: Die Herzlichkeit war Freundlichkeit, der Freund ist eine klare Grenze", "Gemischt: Sie zeigt Interesse, aber ihr Beziehungsstatus steht dem entgegen"]'::jsonb, 'Sie war freundlich, nicht romantisch interessiert. Der Freund ist eine klare Grenze.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51f130a3-2032-4c6f-b654-83d546e7b8aa', 'de', 'Party. Sie ist höflich, aber du bist unsicher. Welche Sätze helfen?', '["„Ich hol mir was zu trinken. Kommst du mit?“", "„Die Party ist irgendwie langweilig.“", "„Ich lass dich mal weiter unter die Leute.“", "„Komm, ich stell dir meine Freunde vor.“"]'::jsonb, 'Ein klarer Vorschlag zeigt ohne Druck, ob sie mitkommen, sich anschließen oder weitermachen will.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('520ac978-94f9-404d-aabe-55099eebb89e', 'de', 'Sie erzählt von ihrem Auslandsstudium. Welche Reaktion kommt ohne Hintergedanken aus?', '["Interessiert fragen, was ihr dort am besten gefallen hat", "Ihr Aussehen loben, um Anziehung aufzubauen", "Schnell auf ihre Nummer drängen", "Nur von deinen eigenen Erfolgen erzählen"]'::jsonb, 'Echtes Interesse an ihrer Geschichte gibt ihr das Gefühl, gesehen und nicht gejagt zu werden.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('530f7582-4d63-4e0c-bede-bf88b8fdbd71', 'de', 'Warum nimmt „Ich kann nur kurz bleiben“ Druck raus?', '["Sie weiß, dass sie nicht in einem endlosen Gespräch mit einem Fremden feststeckt", "Es zeigt, dass du ihre Zeit respektierst und nicht verschwendest", "Begrenzte Zeit erzeugt Dringlichkeit"]'::jsonb, 'Ein Zeitlimit zeigt, dass du gleich wieder gehst, und sie wird weniger vorsichtig.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('55289809-9c93-4056-aed5-077280b1ae2f', 'de', 'Was ist die größte Stärke direkter Opener?', '["Du fühlst dich beim Ansprechen selbstbewusster", "Sie steigern die Anziehung durch Mut", "Sie räumen Unklarheit aus, weil du deine Absicht sofort sagst"]'::jsonb, 'Direkt zu sein erspart das Rätselraten und kommt gleich zur Sache.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5645caed-20b5-412a-abcf-de263b1e3c46', 'de', 'Sie scrollt auf ihrem Handy. Was muss dein Opener leisten, damit er funktioniert?', '["Höflich sein", "Lauter sein", "Interessant sein", "Kurz und knackig sein"]'::jsonb, 'Dein Opener muss interessanter sein als das, was sie vorher gemacht hat.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('59132ed6-d432-4176-9308-5f83ffeb2e2c', 'de', 'Warum führt ein Lächeln Männer beim Ansprechen oft in die Irre?', '["Ein Lächeln signalisiert immer Anziehung", "Lächeln ist eine übliche soziale Höflichkeit", "Männer halten Herzlichkeit für Interesse", "Beides: Lächeln ist oft Höflichkeit, und Männer halten Herzlichkeit für Interesse"]'::jsonb, 'Ein Lächeln ist oft Höflichkeit, und Männer deuten Herzlichkeit häufig als Anziehung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5a89ed7d-2ccb-4fb2-ad5a-c8b0d73aab44', 'de', 'Sie reagiert höflich, aber knapp auf deinen Opener. Womit behältst du den Rahmen in der Hand?', '["Noch eine spannende Frage stellen und weiterführen", "Dich für die Störung entschuldigen und gehen", "Warten, bis sie dir Fragen stellt", "Dich ihrer geringen Energie anpassen und neutral bleiben"]'::jsonb, 'Du gibst die Richtung vor. Führ weiter, statt ihrem Rückzug zu folgen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5b1abc4a-c6ad-4dd2-b4a0-e8c4cf55f119', 'de', 'Warum liest das Gehirn Körperbewegungen vor Worten?', '["Es verarbeitet zuerst das Gesagte", "Bewegung zeigt instinktiv Absicht und Sicherheit", "Fließende Bewegung zeigt Wohlgefühl", "Angespannte Bewegung strahlt Nervosität aus"]'::jsonb, 'Entspannte Bewegungen vermitteln Sicherheit, und das Gespräch fällt ihr leichter.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5b40af44-7fc8-4e4e-93fe-427ce1753d12', 'de', 'Bar. Du sprichst sie an. Sie dreht sich kaum um, sagt tonlos „hey“ und schaut sich im Raum um, während du redest.', '["Höflich: das Nötigste an Höflichkeit. Halt es kurz oder geh", "Kühl: klares Desinteresse. Zieh dich sofort zurück", "Test: Sie will sehen, ob du trotz wenig Energie deinen Rahmen hältst"]'::jsonb, 'Verschlossene Körpersprache wiegt schwerer als ihre Antworten. Zieh dich zurück und geh ruhig.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5bd1ec51-0293-467c-b328-37d4c947a52a', 'de', 'Ihr steht beide in einer langen Schlange im Café. Welche indirekten Opener gibt es?', '["Fragen, was sie hier normalerweise bestellt", "Ihr Lächeln loben", "Etwas dazu sagen, wie langsam es vorangeht", "Dich sofort vorstellen"]'::jsonb, 'Gemeinsame Situationen bieten natürliche Einstiege ohne Druck.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5c6d17f6-baa9-4899-916b-fc9639e67f2c', 'de', 'Ihr Handy hat eine sehr auffällige Hülle. Womit könntest du einsteigen, um sie neugierig zu machen?', '["„Woher hast du die Handyhülle?“", "„Bist du zufrieden mit deinem Handy?“", "„Deine Handyhülle ist interessant.“", "„Ich hab eine Frage zu der Handyhülle.“"]'::jsonb, 'Die Ankündigung macht neugierig, bevor du die eigentliche Frage stellst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5e1e4ba0-77d1-47d1-b948-830f42c9bfc1', 'de', 'Was passiert, wenn du im Gespräch hastig sprichst?', '["Man versteht dich schlechter", "Es zeigt Anspannung", "Es bringt den Rhythmus durcheinander", "Alle oben genannten"]'::jsonb, 'Wenn du hetzt, versteht man dich schlechter, und deine Nervosität wird sichtbar. Sprich langsamer.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5e77a13d-51fd-4fc8-8b20-e153be35f50a', 'de', 'Was bedeutet eine höfliche Reaktion meistens?', '["Sie hat Interesse, testet aber dein Selbstbewusstsein und deinen Rahmen", "Sie ist nett, um Streit zu vermeiden, hat aber null Interesse", "Sie ist unsicher oder nicht ganz offen. Mach langsam weiter oder geh"]'::jsonb, 'Höflich heißt unsicher oder verschlossen. Lies ihre nächsten Signale genau.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5f79a125-3233-4761-a27a-0c3df5b785b6', 'de', 'Was passiert, wenn du ein Zeitlimit setzt?', '["Der Druck sinkt, weil das Ende des Gesprächs schon feststeht", "Sie entspannt sich, weil sie weiß, dass es nicht lange dauert", "Du erzeugst Dringlichkeit, durch die sie das Gespräch mehr schätzt"]'::jsonb, 'Ein Zeitlimit nimmt ihr die Angst, festzustecken, und sie fühlt sich wohler.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('60bdd118-0868-4732-a177-bad97e1d37de', 'de', 'Sie hat ein kleines Tattoo am Handgelenk. Womit könntest du einsteigen, um sie neugierig zu machen?', '["„Cooles Tattoo. Was ist das?“", "„Das Tattoo sieht schön aus.“", "„Ich muss dich was zu dem Tattoo fragen.“", "„Hast du noch mehr Tattoos?“"]'::jsonb, 'Die Ankündigung macht neugierig, bevor du die eigentliche Frage stellst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('610a475a-54e4-4882-b442-6ebc0faac3a8', 'de', 'Ihr steht beide in einer langen Schlange im Café. Welcher indirekte Opener funktioniert am besten?', '["„Du bist echt hübsch, ich musste kurz Hallo sagen.“", "„Was ist deine Nummer?“", "„Die Schlange ist heute echt lächerlich, oder?“", "„Du siehst aus, als bräuchtest du einen Kaffee.“"]'::jsonb, 'Eine Bemerkung zur Situation wirkt natürlich und nimmt Druck raus.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('611e32cc-c038-42d3-a1ce-086d78cbcd68', 'de', 'Sie antwortet knapp, schaut weg und tritt von einem Fuß auf den anderen. Beste Reaktion?', '["Tiefere Fragen stellen", "Sie leicht aufziehen", "Dich sauber verabschieden", "Mehr Energie reinlegen"]'::jsonb, 'Höfliche Rückzugssignale heißen: Zeit zu gehen. Verabschiede dich sauber, ohne zu drängen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('61e8562c-6ad4-4305-bf8f-d44fe44652ab', 'de', 'Was ist die entscheidende Veränderung in der Einstellung, wenn du aus Neugier ansprichst?', '["„Kann ich hier etwas rausholen?“", "„Finde ich diesen Menschen interessant?“", "„Wie kann ich sie schnell beeindrucken?“", "„Wird daraus ein Date?“"]'::jsonb, 'Interesse an ihrer Welt nimmt die Hintergedanken raus und macht ein echtes Gespräch möglich.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6212b078-0050-447a-bf0f-ff2070f3f00c', 'de', 'Schlange im Café. Du sprichst sie an. Sie lächelt kurz, sagt „ja“ und schaut dann aufs Handy.', '["Neutral: Sie ist abgelenkt, macht aber vielleicht mit, wenn du dranbleibst", "Höflich: Sie hat dich wahrgenommen, sich aber sofort abgewandt", "Kühl: Der Blick aufs Handy ist eine bewusste Abfuhr"]'::jsonb, 'Sie hat dich wahrgenommen und dann eine Grenze gezogen. Zieh dich zurück, ohne es in die Länge zu ziehen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('624f3918-37e1-4cec-8932-2afa6e870e81', 'de', 'Ihr steckt beide im Regen an der Bushaltestelle fest. Welcher Opener nimmt Druck raus?', '["„Du siehst selbst im Regen umwerfend aus.“", "„Willst du meine Nummer?“", "„Darf ich mit unter deinen Schirm?“", "„Was für ein Wetter. Weißt du, ob der Bus wieder Verspätung hat?“"]'::jsonb, 'Eine gemeinsame Situation bringt ein Gespräch ganz natürlich in Gang.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('645565d5-3468-40e0-a262-b135680333a7', 'de', 'An ihrer Tasche hängt ein Schlüsselanhänger von einem kleinen Festival. Welcher Opener zeigt Neugier?', '["„Cooler Schlüsselanhänger.“", "„Deine Tasche hat Charakter.“", "„Du fährst auf Events?“", "„Warst du auf dem Festival? Soll ja ziemlich wild sein.“"]'::jsonb, 'Neugier auf ihre Erlebnisse lädt zu einer echten Verbindung ein, ohne Hintergedanken.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('66e6b51f-4377-41cc-af99-be7fc8703380', 'de', 'Tagsüber im Fitnessstudio. Sie macht gerade Satzpause. Was tust du am besten?', '["Warten, bis sie mit dem Training ganz fertig ist", "In ihr Blickfeld gehen, Blickkontakt suchen, lächeln und sie in der Pause ansprechen", "Sie bitten, dich zu sichern oder deine Technik anzuschauen, als natürlichen Einstieg", "Im Fitnessstudio passt das nicht, lass es"]'::jsonb, 'Die Satzpause ist ein kurzes Zeitfenster. Komm sichtbar und mit Blickkontakt, damit sie sich nicht erschreckt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6854fe8c-37a2-4b05-abb5-8e28e81f85df', 'de', 'Auf der Straße. Sie ist höflich, aber du bist unsicher. Welche Sätze helfen, ihr Interesse einzuschätzen?', '["„Ich muss eh in die Richtung. Kommst du mit?“", "„Und, wo willst du hin?“", "„Lust, mal einen Kaffee trinken zu gehen?“", "„Du wirkst interessant.“"]'::jsonb, 'Ein Vorschlag, jetzt mitzugehen oder sich später zu treffen, zeigt ihr Interesse durch Handeln, nicht durch Komplimente.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6ae58be8-fa28-4df9-982d-734c8bf6bc6b', 'de', 'Der Moment ist vorbei, und du bereust es sofort. Woran liegt das?', '["An einer Abfuhr nach einem Versuch", "An ihrem fehlenden Interesse", "An einem Gespräch, das ins Leere lief", "Daran, dass du die Chance ungenutzt gelassen hast"]'::jsonb, 'Reue kommt von verpassten Chancen, nicht von gescheiterten Versuchen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6c9441f0-7531-4148-a292-db648381ccf0', 'de', 'Buchladen. Wie könnte ein Opener lauten, der nach ihrer Meinung fragt?', '["„Ich brauch mal deine Meinung: Sind Bücher gute Geschenke?“", "„Weißt du, wo die Romane stehen?“", "„Entschuldigung, liest du gerade was Spannendes?“"]'::jsonb, 'Wenn du sagst, dass du ihr Urteil brauchst, fühlt sie sich sofort geschätzt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6d84a13d-95e6-437d-9368-891c4d42990a', 'de', 'Welche Signale deuten meist auf Offenheit hin?', '["Gegenfragen", "Sie wendet sich dir zu", "Sie beantwortet Fragen", "Eine entspannte Haltung"]'::jsonb, 'Gegenfragen und Zuwendung zeigen Interesse. Nimm sie als grünes Licht weiterzumachen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6e852fdc-853b-47ca-bd28-81f1c157b93e', 'de', 'Wo funktionieren direkte Opener am besten?', '["In Bars, Clubs, auf Partys und gesellschaftlichen Events", "In ruhigen Bibliotheken oder Büros", "Im Supermarkt zur Stoßzeit", "In Bus und Bahn auf dem Weg zur Arbeit"]'::jsonb, 'Wo man ohnehin Leute kennenlernen will, wirkt romantisches Interesse ganz normal.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6ead40bd-0dee-4b4c-935e-8cf034256a37', 'de', 'Club. Du sagst: „Du bist mir aufgefallen.“ Sie lächelt, sagt danke, wendet sich aber wieder ihren Freundinnen zu.', '["Ihr auf die Schulter tippen und versuchen weiterzureden", "Dich ihren Freundinnen vorstellen, um im Gespräch zu bleiben", "Dich sauber verabschieden: Wahrnehmen ohne Einlassen ist eine höfliche Absage"]'::jsonb, 'Lächeln und Abwenden ist eine höfliche Abfuhr. Wer danach bleibt, zeigt wenig Feingefühl.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('702ce88e-2efa-49c5-9ee5-e08ed426d983', 'de', 'Was macht Neugier-Opener wirksam?', '["Sie fragen nach ihrer Meinung oder Sicht, nicht nur nach Fakten", "Sie sind interessanter als vorhersehbare Sachfragen", "Sie bringen Themen auf, zu denen sie ganz natürlich etwas zu sagen hat", "Alle oben genannten"]'::jsonb, 'Wenn eine Information unvollständig ist, will das Gehirn sie ergänzen. Nutz das, um Aufmerksamkeit zu wecken.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('722e2188-0d60-460b-8ec7-ca6850661d5a', 'de', 'Sie hat eine bunte, handbemalte Handyhülle. Welcher Opener bringt sie ins Gespräch?', '["„Coole Handyhülle.“", "„Du hast guten Stil.“", "„Wie spät ist es?“", "„Sieht aus, als hättest du die Handyhülle selbst gemacht.“"]'::jsonb, 'Eine konkrete Vermutung bringt sie dazu, sich einzubringen und persönlich zu antworten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('727d61fb-ef06-4574-b2e1-63fb70f840c8', 'de', 'Was ist das Hauptziel eines starken Rahmens zum Einstieg?', '["Beeindrucken", "Abfuhren ausschließen", "Interesse wecken", "Stille vermeiden"]'::jsonb, 'Der Einstieg sollte Neugier und echte Anteilnahme wecken.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('732636f6-4948-4cf7-ab3c-1529a104b4c8', 'de', 'Welche Reaktionen heißen meist, dass es Zeit zu gehen ist?', '["Antworten aus einem Wort", "Sie wendet sich ab", "Keine Gegenfragen", "Sie beantwortet Fragen"]'::jsonb, 'Mehrere Rückzugssignale auf einmal heißen: Zeit zu gehen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('75d003ed-f14a-4b05-a68f-d5a813844935', 'de', 'Nach deinem Opener erzählt sie begeistert, was sie denkt. Dein nächster Schritt?', '["Sofort nach ihrer Nummer fragen", "Ihr erst mal deine eigene Meinung sagen", "Schnell das Thema wechseln", "Zuhören und auf ihre Sicht eingehen"]'::jsonb, 'Wenn du auf ihrer Antwort aufbaust, würdigst du ihre Mühe und hältst den Schwung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('761e81ae-f2b8-48ba-a7a0-a8ebe688a7e5', 'de', 'Auf der Straße. Du machst eine Bemerkung. Sie wird langsamer, lächelt und geht neben dir her.', '["Sie fühlt sich verpflichtet, auf dich einzugehen", "Sie ist offen und bleibt bewusst im Gespräch", "Sie ist neutral und wartet, bis du fertig bist"]'::jsonb, 'Dass sie ihr Tempo an deins anpasst, zeigt freiwilliges Interesse. Mach weiter.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('77d7bb74-c3e1-4044-bfb0-c36b1415c65e', 'de', 'Warum solltest du Signale respektieren, auch wenn du unsicher bist, ob sie höflich oder offen ist?', '["Lieber bei höflichen Signalen gehen, als über kühle hinwegzugehen", "Unsicherheit zu respektieren zeigt Feingefühl", "Ihr Wohlgefühl ist wichtiger als dein Bedürfnis, „sicherzugehen“, dass sie Interesse hat", "Alle oben genannten"]'::jsonb, 'Wenn du unsicher bist, richte dich nach dem Signal, das weniger Interesse zeigt. Ihr Wohlgefühl geht vor.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('78cf663a-b29b-480e-a8ef-fe1997c76016', 'de', 'Du gehst hin und sagst: „Kann ich mich zu euch stellen?“ Sie sagen klar, reden aber unter sich weiter.', '["Auf eine Gesprächspause warten und dich dann vorstellen", "Einen Witz machen, um ihre Aufmerksamkeit zurückzuholen", "Gehen: Du hast gefragt, ob du in ihren Rahmen darfst, statt einen eigenen zu setzen"]'::jsonb, 'Wenn du fragst, ob du dazukommen darfst, trittst du in ihre Welt ein. Schaff deine eigene, indem du mit Inhalt einsteigst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7b6ea2f2-5183-4215-9488-2a520d528b32', 'de', 'Was bewirkt ruhiger, freundlicher Blickkontakt, bevor du etwas sagst?', '["Er erzeugt sofort starke Anziehung", "Er zwingt sie, schnell zu reagieren", "Er zeigt ohne Worte eine positive Absicht", "Er verbirgt deine Annäherung komplett"]'::jsonb, 'Ein warmer, freundlicher Blick signalisiert ihrem Nervensystem Sicherheit.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7b879d11-d60e-408e-b0dd-18f2dc6a1bab', 'de', 'Ihr wartet beide am Flughafen auf einen verspäteten Flug. Welcher Opener nimmt Druck raus?', '["„Du wirkst gestresst. Lust zu quatschen?“", "„Krieg ich deine Nummer, für die Wartezeit?“", "„Du bist selbst bei der Verspätung attraktiv.“", "„Die Verspätung ist echt hart. Weißt du, wie lange es noch dauert?“"]'::jsonb, 'Eine gemeinsame Situation bringt ein Gespräch ganz natürlich in Gang.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7d344225-54cf-45ff-b8bc-1f401a89453f', 'de', 'Was vermitteln entspannte Bewegungen?', '["Dass du das Gefühl hast, an diesen Ort zu gehören", "Dass dein Körper keine Anspannung oder Unbehagen ausstrahlt", "Dass du genau diese Situation schon geübt hast"]'::jsonb, 'Fließende Bewegungen zeigen, dass du dich wohlfühlst und dazugehörst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7e53f4ec-68aa-4155-b6ff-8c9214acf8e2', 'de', 'Was ist die größte Schwäche direkter Opener?', '["Sie funktionieren nur in bestimmten sozialen Umgebungen", "Sie verlangen mehr sprachliches Geschick als indirekte Opener", "Wenn sie sich nicht sofort angezogen fühlt, ist das Gespräch schnell vorbei"]'::jsonb, 'Bei direkten Openern schätzt sie dich sofort ein. Es gibt keine Verbindung, die das abfedert.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('80d3365a-d883-4997-8988-b8010451c01d', 'de', 'Du gehst auf sie zu, aber sie weicht sofort zurück. Was ist der wahrscheinlichste Grund?', '["Du bist ihr zu nah gekommen oder hast ihr den Weg versperrt", "Sie hat kein Interesse und schafft bewusst Abstand", "Sie muss irgendwohin"]'::jsonb, 'Zurückweichen ist eine reflexhafte Schutzreaktion, kein bewusstes Urteil.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('81df7422-a32e-4d7e-9ee5-03e32f5773ef', 'de', 'Welcher psychologische Mechanismus macht Opener mit einer Vermutung wirksam?', '["Sie machen neugierig, wie du auf diesen Eindruck gekommen bist", "Sie schmeicheln ihrem Ego", "Sie senken das Risiko einer Abfuhr"]'::jsonb, 'Eine Vermutung macht neugierig darauf, wie du sie siehst, und hält sie gedanklich im Gespräch.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('862f73dc-ec2a-4136-a805-782b65c7eece', 'de', 'Wozu kann ein einziges Gespräch führen?', '["Zu Freundschaften, Beziehungen oder Chancen, mit denen du nicht gerechnet hast", "Zu Erlebnissen und Geschichten, an die du dich jahrelang erinnerst", "Dazu, jemanden zu treffen, der wichtig in deinem Leben wird", "Alle oben genannten"]'::jsonb, 'Gespräche können Möglichkeiten schaffen, die weit über den Moment hinausreichen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('884ee9cb-5bc8-4593-8032-1bb68fe20856', 'de', 'Ihr seid beide auf einem Konzert. Was ist ein indirekter Opener?', '["Fragen, ob sie die Band oder den Künstler schon mal gesehen hat", "Etwas zum Publikum oder zur Location sagen", "Ihr sagen, dass sie einen tollen Musikgeschmack hat"]'::jsonb, 'Wenn du beim gemeinsamen Erlebnis bleibst, kann sich ganz natürlich Vertrautheit aufbauen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('88ec90e6-280c-40aa-896c-018951f9446c', 'de', 'Sie liest ein Buch, dessen Cover du kennst. Welcher Opener zeigt Neugier?', '["„Du wirkst, als würdest du viel lesen.“", "„Ist das die neue Ausgabe? Wie gefällt sie dir bisher?“", "„Gute Wahl. Du siehst klug aus.“", "„Darf ich mich dazusetzen?“"]'::jsonb, 'Neugier auf ihre Erlebnisse lädt zu einer echten Verbindung ein, ohne Hintergedanken.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
